# Feedback 作业平台：把 codex 会话轨迹整理成可读的过程记录，供本机评审使用。
import json
import sys
from pathlib import Path


def clip(value, limit):
    text = " ".join(str(value or "").split())
    if len(text) <= limit:
        return text
    return text[:limit] + "…"


def item_line(item):
    kind = item.get("type") or "未知条目"
    if kind == "UserMessage":
        text = " ".join(part.get("text", "") for part in item.get("content", []) if part.get("text"))
        return "用户任务", clip(text, 1500)
    if kind == "AgentMessage":
        text = " ".join(part.get("text", "") for part in item.get("content", []) if part.get("text"))
        return "模型回复", clip(text, 1500)
    if kind == "Reasoning":
        parts = item.get("raw_content") or item.get("summary_text") or []
        return "模型思考", clip(" ".join(str(part) for part in parts), 500)
    if kind == "CommandExecution":
        command = item.get("command")
        if isinstance(command, list):
            command = " ".join(str(part) for part in (command[2:] if len(command) > 2 else command) if part)
        output = clip(item.get("stdout") or "", 500)
        return "执行命令", f"{clip(command, 400)} | 状态 {item.get('status')} | 输出 {output}"
    if kind == "FileChange":
        changes = item.get("changes") or {}
        detail = ", ".join(f"{name} ({value.get('type')})" for name, value in changes.items())
        return "改动文件", clip(detail, 500)
    return kind, clip(json.dumps(item, ensure_ascii=False), 400)


# codex-relay 的 stdout 事件格式：会话被中途终止时，轨迹里保存的是这些原始事件。
def relay_line(event):
    kind = event.get("type")
    if kind == "thread.started":
        return "会话开始", f"session={event.get('thread_id') or event.get('threadId') or ''}"
    if kind == "turn.started":
        return "turn 开始", ""
    if kind == "turn.completed":
        return "turn 完成", ""
    if kind in ("turn.failed", "error"):
        message = event.get("message") or (event.get("error") or {}).get("message")
        return "错误", clip(message, 500)
    # item.started 与 item.completed 是同一件事的前后两条，只保留带结果的 completed。
    if kind != "item.completed":
        return "", ""
    item = event.get("item")
    if not isinstance(item, dict):
        return "", ""
    item_type = item.get("item_type") or item.get("type") or "条目"
    if item_type == "agent_message":
        return "模型回复", clip(item.get("text"), 1500)
    if item_type == "reasoning":
        return "模型思考", clip(item.get("text") or item.get("summary"), 500)

