        return "会话开始", f"session={event.get('thread_id') or event.get('threadId') or ''}"
    if kind == "turn.started":
        return "turn 开始", ""
    if kind == "turn.completed":
        return "turn 完成", ""
    if kind in ("turn.failed", "error"):
        message = event.get("message") or (event.get("error") or {}).get("message")
        return "错误", clip(message, 500)
    # item.started 与 item.completed 是同一件事的前后两条，只保留带结果的 completed。
    if kind != "item.completed":
        return "", ""
    item = event.get("item")
    if not isinstance(item, dict):
        return "", ""
    item_type = item.get("item_type") or item.get("type") or "条目"
    if item_type == "agent_message":
        return "模型回复", clip(item.get("text"), 1500)
    if item_type == "reasoning":
        return "模型思考", clip(item.get("text") or item.get("summary"), 500)

