// Package vulndedup implements cross-cluster vulnerability deduplication,
// attribution and workload aggregation.
//
// The package is intentionally dependency free (standard library only) so the
// aggregation logic can be unit tested and reused by every delivery channel
// (HTTP reporters, background jobs or offline reports).
//
// The central input is a flat list of Finding values. A Finding represents a
// single detection of a vulnerability on a concrete resource (container image
// or host) that belongs to a workload inside a Kubernetes cluster. Repeated
// Findings with the same CVE produced by different clusters/scans are merged
// into one DeduplicatedVulnerability while every occurrence is retained for
// drill-down.
package vulndedup

import "strings"

// DedupGranularity controls when two Findings are considered the same
// vulnerability for the merged view.
type DedupGranularity string

const (
	// DedupByCVE collapses every occurrence of the same CVE into a single
	// entry regardless of the affected package. This is the cross-cluster
	// "one CVE counted once" view required by the acceptance criteria.
	DedupByCVE DedupGranularity = "cve"

	// DedupByCVEAndPackage keeps the same CVE affecting different packages
	// (or package paths) as distinct entries, matching ThreatMapper's native
	// Vulnerability node identity (package path + package + CVE).
	DedupByCVEAndPackage DedupGranularity = "cve_package"
)

// ParseGranularity normalizes a user supplied granularity. Unknown or empty
// values fall back to DedupByCVE.
func ParseGranularity(value string) DedupGranularity {
	switch DedupGranularity(strings.ToLower(strings.TrimSpace(value))) {
	case DedupByCVEAndPackage:
		return DedupByCVEAndPackage
	case DedupByCVE:
		return DedupByCVE
	default:
		return DedupByCVE
	}
}

// Finding is one occurrence of a vulnerability. It is the flattened row that
// the graph/reporting layer is expected to produce.
type Finding struct {
	// Vulnerability identity / metadata.
	NodeID      string  `json:"node_id,omitempty"`
	CVEID       string  `json:"cve_id"`
	RuleID      string  `json:"rule_id,omitempty"`
	Severity    string  `json:"cve_severity,omitempty"`
	CVSSScore   float64 `json:"cve_cvss_score,omitempty"`
	FixedIn     string  `json:"cve_fixed_in,omitempty"`
	PackageName string  `json:"cve_caused_by_package,omitempty"`
	PackagePath string  `json:"cve_caused_by_package_path,omitempty"`
	Link        string  `json:"cve_link,omitempty"`
	Description string  `json:"cve_description,omitempty"`

	// Attribution: where the occurrence was observed.
	ClusterID   string `json:"cluster_id,omitempty"`
	ClusterName string `json:"cluster_name,omitempty"`
	Namespace   string `json:"namespace,omitempty"`

	WorkloadID   string `json:"workload_id,omitempty"`
	WorkloadName string `json:"workload_name,omitempty"`
	WorkloadKind string `json:"workload_kind,omitempty"`

	PodID       string `json:"pod_id,omitempty"`
	PodName     string `json:"pod_name,omitempty"`
	ContainerID string `json:"container_id,omitempty"`

	ImageID     string `json:"image_id,omitempty"`
	ImageName   string `json:"image_name,omitempty"`
	ImageDigest string `json:"image_digest,omitempty"`

	HostID   string `json:"host_id,omitempty"`
	HostName string `json:"host_name,omitempty"`

	ScanID    string `json:"scan_id,omitempty"`
	UpdatedAt int64  `json:"updated_at,omitempty"`
}

// normalizeCVE returns the canonical CVE identifier. CVE ids are
// conventionally upper case; normalizing avoids counting "cve-2024-1" and
// "CVE-2024-1" twice.
func normalizeCVE(cve string) string {
	return strings.ToUpper(strings.TrimSpace(cve))
}

func normalizeValue(value string) string {
	return strings.TrimSpace(value)
}

// Identity returns the de-duplication key of the finding for the requested
// granularity. Findings sharing an identity are merged into one entry.
//
// When the finding has no CVE id, the native node/rule id is used so that
// non-CVE findings are never collapsed into a single empty bucket.
func (f Finding) Identity(granularity DedupGranularity) string {
	cve := normalizeCVE(f.CVEID)
	if cve == "" {
		if id := normalizeValue(f.NodeID); id != "" {
			return "node:" + id
		}
		if id := normalizeValue(f.RuleID); id != "" {
			return "rule:" + id
		}
		return "unknown"
	}

	if granularity == DedupByCVEAndPackage {
		return strings.Join([]string{
			cve,
			normalizeValue(f.PackageName),
			normalizeValue(f.PackagePath),
		}, "/")
	}
	return cve
}

// DisplayCVE returns the normalized CVE id or a stable placeholder.
func (f Finding) DisplayCVE() string {
	if cve := normalizeCVE(f.CVEID); cve != "" {
		return cve
	}
	if f.RuleID != "" {
		return f.RuleID
	}
	return f.NodeID
}

// NormalizeSeverity canonicalizes a severity string to one of the ThreatMapper
// severity buckets.
func NormalizeSeverity(severity string) string {
	switch strings.ToLower(strings.TrimSpace(severity)) {
	case "critical":
		return "critical"
	case "high":
		return "high"
	case "medium", "moderate":
		return "medium"
	case "low":
		return "low"
	case "info", "informational", "negligible":
		return "info"
	default:
		return "unknown"
	}
}

// severityRank orders severities by urgency. Higher is more severe.
func severityRank(severity string) int {
	switch NormalizeSeverity(severity) {
	case "critical":
		return 5
	case "high":
		return 4
	case "medium":
		return 3
	case "low":
		return 2
	case "info":
		return 1
	default:
		return 0
	}
}

package vulndedup

// EntityRef is a minimal reference to a graph entity involved in an
// attribution.
type EntityRef struct {
	NodeID string `json:"node_id"`
	Name   string `json:"name"`
}

// ClusterAttribution describes where a deduplicated vulnerability was found
// inside one cluster.
type ClusterAttribution struct {
	ClusterID   string `json:"cluster_id"`
	ClusterName string `json:"cluster_name"`

	// OccurrenceCount is the number of raw findings in this cluster.
	OccurrenceCount int `json:"occurrence_count"`
	// ImageCount / HostCount / WorkloadCount are distinct resources.
	ImageCount    int `json:"image_count"`
	HostCount     int `json:"host_count"`
	WorkloadCount int `json:"workload_count"`
}

// WorkloadAttribution describes a workload affected by a deduplicated
// vulnerability.
type WorkloadAttribution struct {
	WorkloadID   string `json:"workload_id"`
	WorkloadName string `json:"workload_name"`
	WorkloadKind string `json:"workload_kind"`
	Namespace    string `json:"namespace"`
	ClusterID    string `json:"cluster_id"`
	ClusterName  string `json:"cluster_name"`

	OccurrenceCount int `json:"occurrence_count"`
	ImageCount      int `json:"image_count"`
	HostCount       int `json:"host_count"`
}

// ResourceAttribution is a distinct image or host carrying a vulnerability,
// together with the places it was observed. It is the drill-down target.
type ResourceAttribution struct {
	NodeID   string `json:"node_id"`
	Name     string `json:"name"`
	NodeType string `json:"node_type"`
	Digest   string `json:"digest,omitempty"`

	OccurrenceCount int      `json:"occurrence_count"`
	ClusterIDs      []string `json:"cluster_ids"`
	ClusterNames    []string `json:"cluster_names,omitempty"`
	WorkloadIDs     []string `json:"workload_ids,omitempty"`
	HostIDs         []string `json:"host_ids,omitempty"`
	ImageIDs        []string `json:"image_ids,omitempty"`
}

// DeduplicatedVulnerability is one logical vulnerability (one CVE by default)
// merged from every cluster/scan occurrence.
type DeduplicatedVulnerability struct {
	// Identity of the merged entry.
	DedupKey string `json:"dedup_key"`
	CVEID    string `json:"cve_id"`
	RuleID   string `json:"rule_id,omitempty"`

	// Representative metadata (taken from the most severe occurrence).
	Severity    string  `json:"cve_severity"`
	CVSSScore   float64 `json:"cve_cvss_score"`
	FixedIn     string  `json:"cve_fixed_in,omitempty"`
	Link        string  `json:"cve_link,omitempty"`
	Description string  `json:"cve_description,omitempty"`

	// Distinct package coordinates affected by this CVE.
	PackageNames []string `json:"package_names,omitempty"`

	// Multiplicity / reach.
	OccurrenceCount int `json:"occurrence_count"`
	ClusterCount    int `json:"cluster_count"`
	WorkloadCount   int `json:"workload_count"`
	ImageCount      int `json:"image_count"`
	HostCount       int `json:"host_count"`

	// Attribution / drill-down.
	Clusters  []ClusterAttribution  `json:"clusters"`
	Workloads []WorkloadAttribution `json:"workloads"`
	Images    []ResourceAttribution `json:"images"`
	Hosts     []ResourceAttribution `json:"hosts"`

	// Occurrences retains every raw finding so callers can drill all the way
	// down to the concrete image/host/scan.
	Occurrences []Finding `json:"occurrences,omitempty"`
}

// SeverityCounts holds per-severity totals.
type SeverityCounts struct {
	Critical int `json:"critical"`
	High     int `json:"high"`
	Medium   int `json:"medium"`
	Low      int `json:"low"`
	Info     int `json:"info"`
	Unknown  int `json:"unknown"`
}

// Map returns the severity counts as the legacy map shape used by ThreatMapper
// category counts.
func (s SeverityCounts) Map() map[string]int32 {
	return map[string]int32{
		"critical": int32(s.Critical),
		"high":     int32(s.High),
		"medium":   int32(s.Medium),
		"low":      int32(s.Low),
		"info":     int32(s.Info),
		"unknown":  int32(s.Unknown),
	}
}

// Reconciliation compares the reported de-duplicated total against an
// independently computed manual expectation (the number of distinct CVE ids).
type Reconciliation struct {
	// RawFindingCount is the number of input occurrence rows.
	RawFindingCount int `json:"raw_finding_count"`
	// ManualDistinctCVE is the "human checked" expectation: distinct CVE ids.
	ManualDistinctCVE int `json:"manual_distinct_cve"`
	// ReportedDeduplicatedTotal is what the aggregation produced.
	ReportedDeduplicatedTotal int `json:"reported_deduplicated_total"`
	// Difference is Reported - Manual. Zero means the totals agree.
	Difference int `json:"difference"`
	// Match is true when Difference == 0.
	Match bool `json:"match"`
}

// Summary contains the headline, de-duplicated counts.
type Summary struct {
	Granularity DedupGranularity `json:"granularity"`

	// TotalFindings is the raw occurrence count (what the legacy API would
	// count), kept for comparison.
	TotalFindings int `json:"total_findings"`

	// TotalVulnerabilities is the de-duplicated total. Under DedupByCVE this
	// equals the number of distinct CVEs and is the acceptance number.
	TotalVulnerabilities int `json:"total_vulnerabilities"`

	// DistinctCVE is the number of distinct CVE ids irrespective of
	// granularity; it is the manual reconciliation reference.
	DistinctCVE int `json:"distinct_cve"`

	ClusterCount  int `json:"cluster_count"`
	WorkloadCount int `json:"workload_count"`
	ImageCount    int `json:"image_count"`
	HostCount     int `json:"host_count"`

	// SeverityCounts counts each de-duplicated vulnerability once.
	SeverityCounts SeverityCounts `json:"severity_counts"`

	Reconciliation Reconciliation `json:"reconciliation"`
}

// WorkloadSummary aggregates de-duplicated vulnerability counts for one
// workload.
type WorkloadSummary struct {
	WorkloadID   string `json:"workload_id"`
	WorkloadName string `json:"workload_name"`
	WorkloadKind string `json:"workload_kind"`
	Namespace    string `json:"namespace"`
	ClusterID    string `json:"cluster_id"`
	ClusterName  string `json:"cluster_name"`

	// OccurrenceCount counts raw findings belonging to the workload.
	OccurrenceCount int `json:"occurrence_count"`
	// UniqueCVE is the number of distinct CVEs in the workload.
	UniqueCVE int `json:"unique_cves"`
	// ImageCount / HostCount are distinct resources for the workload.
	ImageCount int `json:"image_count"`
	HostCount  int `json:"host_count"`

	SeverityCounts SeverityCounts `json:"severity_counts"`

	// CVEs lists the distinct CVE ids (sorted) for drill-down.
	CVEs []string `json:"cves,omitempty"`
}

// Report is the complete cross-cluster, de-duplicated vulnerability view.
type Report struct {
	Summary         Summary                   `json:"summary"`
	Vulnerabilities []DeduplicatedVulnerability `json:"vulnerabilities"`
	Workloads       []WorkloadSummary          `json:"workloads"`
}

